(function() {
  window.CardSpoke.Plugin.register('daily-journal', {
    manifest: {
      name: 'Daily Journal',
      version: '1.0.0',
      author: 'CardSpoke Community',
      description: 'Rebrands CardSpoke as a daily journaling app',
      layer: 'app',
      permissions: ['ui-override', 'storage']
    },
    setup: async function(ctx) {
      var self = this;
      document.body.classList.add('daily-journal-active');
      var headerTitle = document.querySelector('.header h1, header h1');
      if (headerTitle) headerTitle.textContent = 'Daily Journal';
      var fab = document.createElement('button');
      fab.className = 'journal-fab';
      fab.textContent = '+';
      fab.title = 'New journal entry';
      fab.onclick = function() {
        var now = new Date();
        var dateStr = now.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
        var timeStr = now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
        try {
          ctx.api.data.createCard({
            title: dateStr,
            body: '## ' + timeStr + '\n\n',
            tags: ['journal', now.toISOString().slice(0, 7)]
          });
          ctx.api.ui.showToast('Journal entry created for ' + dateStr, 'success');
          updateStreak();
        } catch (err) {
          ctx.logger.error('Failed to create journal entry:', err);
        }
      };
      document.body.appendChild(fab);
      self._fab = fab;
      var streakEl = document.createElement('div');
      streakEl.className = 'journal-streak';
      document.body.appendChild(streakEl);
      self._streakEl = streakEl;
      function updateStreak() {
        var cards = ctx.api.data.listCards();
        var journalCards = cards.filter(function(c) {
          return c.tags && c.tags.indexOf('journal') !== -1;
        });
        var daySet = {};
        journalCards.forEach(function(c) {
          var d = new Date(c.createdAt).toISOString().slice(0, 10);
          daySet[d] = true;
        });
        var streak = 0;
        var today = new Date();
        for (var i = 0; i < 365; i++) {
          var check = new Date(today);
          check.setDate(check.getDate() - i);
          var key = check.toISOString().slice(0, 10);
          if (daySet[key]) {
            streak++;
          } else if (i > 0) {
            break;
          }
        }
        var totalEntries = journalCards.length;
        streakEl.innerHTML = '<span class="journal-streak-count">' + streak + '</span> day streak &middot; ' + totalEntries + ' entries';
      }
      updateStreak();
      self._updateStreak = updateStreak;
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.register({
          name: 'daily-journal-update',
          priority: -100,
          operations: ['card.save', 'card.delete'],
          handler: async function(mwCtx, next) {
            await next();
            setTimeout(function() { updateStreak(); }, 100);
          }
        });
      }
      ctx.logger.info('Daily Journal loaded');
    },
    teardown: async function(ctx) {
      if (window.CardSpoke && window.CardSpoke.Middleware) {
        window.CardSpoke.Middleware.unregister('daily-journal-update');
      }
      document.body.classList.remove('daily-journal-active');
      if (this._fab && this._fab.parentNode) this._fab.remove();
      if (this._streakEl && this._streakEl.parentNode) this._streakEl.remove();
      var headerTitle = document.querySelector('.header h1, header h1');
      if (headerTitle && headerTitle.textContent === 'Daily Journal') {
        headerTitle.textContent = 'CardSpoke';
      }
      ctx.logger.info('Daily Journal disabled');
    }
  });
})();
